":"verb phrase","translationUz":"izlamoq","definitionEn":"trying to discover or obtain something"},{"testNo":4,"passageNo":3,"surface":"task","partOfSpeech":"noun","translationUz":"vazifa","definitionEn":"work that needs to be done"},{"testNo":4,"passageNo":3,"surface":"executives","partOfSpeech":"noun","translationUz":"rahbarlar","definitionEn":"senior managers of companies"},{"testNo":4,"passageNo":3,"surface":"stuck with","partOfSpeech":"phrasal verb","translationUz":"eski usulga yopishib olgan","definitionEn":"continuing to use an outdated approach"},{"testNo":4,"passageNo":3,"surface":"strategies","partOfSpeech":"noun","translationUz":"strategiyalar","definitionEn":"plans for achieving goals"},{"testNo":4,"passageNo":3,"surface":"camera","partOfSpeech":"noun","translationUz":"fotoapparat","definitionEn":"a device used to take photographs"},{"testNo":4,"passageNo":3,"surface":"competition","partOfSpeech":"noun","translationUz":"raqobat","definitionEn":"the contest between sellers for customers"},{"testNo":4,"passageNo":3,"surface":"decade","partOfSpeech":"noun","translationUz":"o‘n yillik","definitionEn":"a period of ten years"},{"testNo":4,"passageNo":3,"surface":"rival products","partOfSpeech":"noun phrase","translationUz":"raqobatchi mahsulotlar","definitionEn":"goods sold by competing firms"},{"testNo":4,"passageNo":3,"surface":"rushed onto","partOfSpeech":"verb phrase","translationUz":"shoshilinch olib chiqilgan","definitionEn":"introduced to the market very quickly"},{"testNo":4,"passageNo":3,"surface":"unimaginable","partOfSpeech":"adjective","translationUz":"tasavvur qilib bo‘lmaydigan","definitionEn":"too extreme to imagine"},{"testNo":4,"passageNo":3,"surface":"headline-hitting","partOfSpeech":"adjective","translationUz":"gazeta sarlavhasiga chiqadigan","definitionEn":"significant enough to attract major news coverage"},{"testNo":4,"passageNo":3,"surface":"despair","partOfSpeech":"verb","translationUz":"tushkunlikka tushmoq","definitionEn":"lose hope of success"},{"testNo":4,"passageNo":3,"surface":"plenty","partOfSpeech":"noun","translationUz":"ko‘plab imkoniyatlar","definitionEn":"a large supply or number"},{"testNo":4,"passageNo":3,"surface":"albeit","partOfSpeech":"conjunction","translationUz":"garchi ... bo‘lsa-da","definitionEn":"even though"},{"testNo":4,"passageNo":3,"surface":"glamorous","partOfSpeech":"adjective","translationUz":"ko‘zga tashlanadigan","definitionEn":"attractive and impressive in public"},{"testNo":4,"passageNo":3,"surface":"claims","partOfSpeech":"verb","translationUz":"ta’kidlaydi","definitionEn":"states something to be true"},{"testNo":4,"passageNo":3,"surface":"roots","partOfSpeech":"noun","translationUz":"asosiy sabablar","definitionEn":"fundamental causes of a trend"},{"testNo":4,"passageNo":3,"surface":"genuine","partOfSpeech":"adjective","translationUz":"haqiqiy","definitionEn":"real and authentic"},{"testNo":4,"passageNo":3,"surface":"revolution","partOfSpeech":"noun","translationUz":"tub o‘zgarish","definitionEn":"a fundamental transformation"},{"testNo":4,"passageNo":3,"surface":"information technology","partOfSpeech":"noun phrase","translationUz":"axborot texnologiyalari","definitionEn":"computing and communications tools"},{"testNo":4,"passageNo":3,"surface":"business processes","partOfSpeech":"noun phrase","translationUz":"biznes jarayonlari","definitionEn":"organised activities through which a firm operates"},{"testNo":4,"passageNo":3,"surface":"from top to bottom","partOfSpeech":"adverb phrase","translationUz":"yuqoridan pastgacha butunlay","definitionEn":"throughout every part of an organisation"},{"testNo":4,"passageNo":3,"surface":"highlights","partOfSpeech":"verb","translationUz":"alohida ko‘rsatadi","definitionEn":"draws attention to an important case"},{"testNo":4,"passageNo":3,"surface":"instances","partOfSpeech":"noun","translationUz":"misollar","definitionEn":"specific cases of an event"},{"testNo":4,"passageNo":3,"surface":"considerably","partOfSpeech":"adverb","translationUz":"sezilarli darajada","definitionEn":"by a large amount"},{"testNo":4,"passageNo":3,"surface":"creativity","partOfSpeech":"noun","translationUz":"ijodkorlik","definitionEn":"the ability to develop original ideas"},{"testNo":4,"passageNo":3,"surface":"notable","partOfSpeech":"adjective","translationUz":"alohida e’tiborga molik","definitionEn":"worthy of particular attention"},{"testNo":4,"passageNo":3,"surface":"retail giant","partOfSpeech":"noun phrase","translationUz":"chakana savdo giganti","definitionEn":"a very large company selling goods to customers"},{"testNo":4,"passageNo":3,"surface":"superficially","partOfSpeech":"adverb","translationUz":"bir qarashda","definitionEn":"when judged only by outward appearance"},{"testNo":4,"passageNo":3,"surface":"mundane","partOfSpeech":"adjective","translationUz":"oddiy","definitionEn":"unremarkable or routine"},{"testNo":4,"passageNo":3,"surface":"shifting","partOfSpeech":"verb","translationUz":"qayta ortish","definitionEn":"moving goods from one truck to another"},{"testNo":4,"passageNo":3,"surface":"suppliers","partOfSpeech":"noun","translationUz":"yetkazib beruvchilar","definitionEn":"companies providing goods to other businesses"},{"testNo":4,"passageNo":3,"surface":"trucks","partOfSpeech":"noun","translationUz":"yuk mashinalari","definitionEn":"large road vehicles for transporting merchandise"},{"testNo":4,"passageNo":3,"surface":"heading for","partOfSpeech":"verb phrase","translationUz":"... tomon yo‘l olgan","definitionEn":"travelling toward a destination"},{"testNo":4,"passageNo":3,"surface":"stores","partOfSpeech":"noun","translationUz":"do‘konlar","definitionEn":"places selling goods"},{"testNo":4,"passageNo":3,"surface":"fundamental","partOfSpeech":"adjective","translationUz":"asosiy","definitionEn":"essential to a successful outcome"},{"testNo":4,"passageNo":3,"surface":"ability","partOfSpeech":"noun","translationUz":"qobiliyat","definitionEn":"the capacity to do something"},{"testNo":4,"passageNo":3,"surface":"outstanding","partOfSpeech":"adjective","translationUz":"mislsiz","definitionEn":"exceptionally good or important"},{"testNo":4,"passageNo":3,"surface":"encouraged","partOfSpeech":"verb","translationUz":"undalmoqda","definitionEn":"being urged to take an action"},{"testNo":4,"passageNo":3,"surface":"embrace","partOfSpeech":"verb","translationUz":"qabul qilib amalga oshirmoq","definitionEn":"adopt an idea enthusiastically"},{"testNo":4,"passageNo":3,"surface":"regional carrier","partOfSpeech":"noun phrase","translationUz":"mintaqaviy aviatashuvchi","definitionEn":"an airline operating flights within a region"},{"testNo":4,"passageNo":3,"surface":"creative strategies","partOfSpeech":"noun phrase","translationUz":"ijodiy strategiyalar","definitionEn":"original approaches to achieving business goals"},{"testNo":4,"passageNo":3,"surface":"timing","partOfSpeech":"noun","translationUz":"vaqtni to‘g‘ri tanlash","definitionEn":"choosing the most suitable moment"},{"testNo":4,"passageNo":3,"surface":"victory","partOfSpeech":"noun","translationUz":"g‘alaba","definitionEn":"success over a competitor"},{"testNo":4,"passageNo":3,"surface":"ailing","partOfSpeech":"adjective","translationUz":"og‘ir ahvoldagi","definitionEn":"performing poorly as a business"},{"testNo":4,"passageNo":3,"surface":"competitor","partOfSpeech":"noun","translationUz":"raqobatchi","definitionEn":"another company competing for customers"},{"testNo":4,"passageNo":3,"surface":"packaging","partOfSpeech":"noun","translationUz":"qadoqlash","definitionEn":"providing containers and wrappers for products"},{"testNo":4,"passageNo":3,"surface":"ready-made containers","partOfSpeech":"noun phrase","translationUz":"tayyor idishlar","definitionEn":"containers manufactured before delivery"},{"testNo":4,"passageNo":3,"surface":"customers","partOfSpeech":"noun","translationUz":"mijozlar","definitionEn":"people or businesses purchasing goods"},{"testNo":4,"passageNo":3,"surface":"machinery","partOfSpeech":"noun","translationUz":"uskunalar","definitionEn":"mechanical devices used for production"},{"testNo":4,"passageNo":3,"surface":"supplying","partOfSpeech":"verb","translationUz":"yetkazib berish","definitionEn":"providing goods or materials"},{"testNo":4,"passageNo":3,"surface":"dedicated materials","partOfSpeech":"noun phrase","translationUz":"maxsus xomashyolar","definitionEn":"materials specifically made for a production method"},{"testNo":4,"passageNo":3,"surface":"switch suppliers","partOfSpeech":"verb phrase","translationUz":"yetkazib beruvchini almashtirmoq","definitionEn":"change from one supplying company to another"},{"testNo":4,"passageNo":3,"surface":"achieved","partOfSpeech":"verb","translationUz":"erishdilar","definitionEn":"successfully attained a goal"},{"testNo":4,"passageNo":3,"surface":"underlying","partOfSpeech":"adjective","translationUz":"asosiy","definitionEn":"forming the fundamental basis"},{"testNo":4,"passageNo":3,"surface":"recommend","partOfSpeech":"verb","translationUz":"tavsiya qilmoq","definitionEn":"advise choosing a particular approach"},{"testNo":4,"passageNo":3,"surface":"demand innovations","partOfSpeech":"noun phrase","translationUz":"talab innovatsiyalari","definitionEn":"innovations based on discovering new forms of market demand"},{"testNo":4,"passageNo":3,"surface":"far-sighted organisations","partOfSpeech":"noun phrase","translationUz":"uzoqni ko‘ra biladigan tashkilotlar","definitionEn":"companies anticipating future changes"},{"testNo":4,"passageNo":3,"surface":"meeting existing demand","partOfSpeech":"verb phrase","translationUz":"mavjud talabni qondirish","definitionEn":"supplying what current customers already want"},{"testNo":4,"passageNo":3,"surface":"discovering","partOfSpeech":"verb","translationUz":"kashf etish","definitionEn":"finding previously unknown possibilities"},{"testNo":4,"passageNo":3,"surface":"adapting","partOfSpeech":"verb","translationUz":"moslashish","definitionEn":"changing to suit new circumstances"},{"testNo":4,"passageNo":3,"surface":"services","partOfSpeech":"noun","translationUz":"xizmatlar","definitionEn":"non-material products supplied for payment"},{"testNo":4,"passageNo":3,"surface":"industrial gas","partOfSpeech":"noun phrase","translationUz":"sanoat gazi","definitionEn":"gas used in industrial processes"},{"testNo":4,"passageNo":3,"surface":"commodity","partOfSpeech":"noun","translationUz":"ommaviy standart tovar","definitionEn":"a widely traded undifferentiated product"},{"testNo":4,"passageNo":3,"surface":"operational income","partOfSpeech":"noun phrase","translationUz":"operatsion daromad","definitionEn":"profit earned from a company's core operations"},{"testNo":4,"passageNo":3,"surface":"skills","partOfSpeech":"noun","translationUz":"ko‘nikmalar","definitionEn":"abilities developed through experience"},{"testNo":4,"passageNo":3,"surface":"gained","partOfSpeech":"verb","translationUz":"orttirgan","definitionEn":"acquired through work or learning"},{"testNo":4,"passageNo":3,"surface":"management services","partOfSpeech":"noun phrase","translationUz":"boshqaruv xizmatlari","definitionEn":"professional help managing related operations"},{"testNo":4,"passageNo":3,"surface":"accompany","partOfSpeech":"verb","translationUz":"hamroh bo‘lmoq","definitionEn":"be provided alongside another product"},{"testNo":4,"passageNo":3,"surface":"profits","partOfSpeech":"noun","translationUz":"foyda","definitionEn":"financial gains after costs"},{"testNo":4,"passageNo":3,"surface":"rose","partOfSpeech":"verb","translationUz":"ko‘tarildi","definitionEn":"increased over a period"},{"testNo":4,"passageNo":3,"surface":"managers","partOfSpeech":"noun","translationUz":"rahbarlar","definitionEn":"people responsible for directing teams"},{"testNo":4,"passageNo":3,"surface":"projects","partOfSpeech":"noun","translationUz":"loyihalar","definitionEn":"planned pieces of work"},{"testNo":4,"passageNo":3,"surface":"potential","partOfSpeech":"noun","translationUz":"salohiyat","definitionEn":"capacity for future success"},{"testNo":4,"passageNo":3,"surface":"rapidly","partOfSpeech":"adverb","translationUz":"tezda","definitionEn":"at high speed"},{"testNo":4,"passageNo":3,"surface":"independent business units","partOfSpeech":"noun phrase","translationUz":"mustaqil biznes bo‘linmalari","definitionEn":"separately operated parts of a company"},{"testNo":4,"passageNo":3,"surface":"smothering influence","partOfSpeech":"noun phrase","translationUz":"bo‘g‘uvchi ta’sir","definitionEn":"pressure that prevents new ideas developing"},{"testNo":4,"passageNo":3,"surface":"ultimate outcome","partOfSpeech":"noun phrase","translationUz":"yakuniy natija","definitionEn":"the final effect of a process"},{"testNo":4,"passageNo":3,"surface":"unpredictable","partOfSpeech":"adjective","translationUz":"oldindan aytib bo‘lmaydigan","definitionEn":"impossible to forecast reliably"},{"testNo":4,"passageNo":3,"surface":"emerges","partOfSpeech":"verb","translationUz":"vujudga keladi","definitionEn":"arises from a process"}],"corrections":[],"offsetRepairs":[]}$plan$::jsonb;
  v_check record;
  v_repair record;
  v_item record;
  v_old record;
  v_passage_id uuid;
  v_body text;
  v_word text;
  v_part text;
  v_lexical_type text;
  v_unit_id uuid;
  v_lexeme_id uuid;
  v_sense_key text;
  v_regex text;
  v_start integer;
  v_total integer;
  v_ordinal integer;
  v_rows integer;
  v_repaired integer := 0;
  v_corrected integer := 0;
  v_inserted integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(11061401);

  -- Fail before any mutation if any source text or catalogue slot changed.
  FOR v_check IN SELECT key, value FROM jsonb_each_text(v_plan->'passages') LOOP
    SELECT COUNT(*), MIN(body_text) INTO v_total, v_body
      FROM reading_passages
      WHERE test_no=split_part(v_check.key,'-',1)::integer
        AND passage_no=split_part(v_check.key,'-',2)::integer;
    IF v_total <> 1 OR v_body IS NULL
       OR encode(extensions.digest(v_body,'sha256'),'hex') <> v_check.value THEN
      RAISE EXCEPTION 'Reading source checksum mismatch: %', v_check.key;
    END IF;
  END LOOP;

  -- Repair exact incorrect spans in passages 002 and 003 without changing IDs.
  FOR v_repair IN
    SELECT * FROM jsonb_to_recordset(v_plan->'offsetRepairs')
      AS r("testNo" integer,"passageNo" integer,id text,surface text,
           "expectedStart" integer,"matchOrdinal" integer)
  LOOP
    SELECT p.id,p.body_text,o.start_char,o.end_char,o.surface_form
      INTO v_old
      FROM lexical_occurrences o
      JOIN reading_passages p ON p.id=o.passage_id
      WHERE o.id=v_repair.id::uuid
        AND p.test_no=v_repair."testNo"
        AND p.passage_no=v_repair."passageNo";
    IF NOT FOUND OR lower(v_old.surface_form) <> lower(v_repair.surface) THEN
      RAISE EXCEPTION 'Reading repair target changed: %',v_repair.id;
    END IF;
    v_regex:='(?i)(?<![[:alpha:]])'||v_repair.surface||'(?![[:alpha:]])';
    v_start:=regexp_instr(v_old.body_text,v_regex,1,v_repair."matchOrdinal")-1;
    IF v_start<0 OR lower(substr(v_old.body_text,v_start+1,length(v_repair.surface)))
       <> lower(v_repair.surface) THEN
      RAISE EXCEPTION 'Reading repair missing or mismatched surface: %',v_repair.id;
    END IF;
    IF v_old.start_char=v_start AND v_old.end_char=v_start+length(v_repair.surface) THEN
      CONTINUE;
    END IF;
    IF v_old.start_char<>v_repair."expectedStart"
       OR EXISTS(SELECT 1 FROM lexical_occurrences o
         WHERE o.passage_id=v_old.id AND o.id<>v_repair.id::uuid
           AND o.start_char<v_start+length(v_repair.surface) AND o.end_char>v_start) THEN
      RAISE EXCEPTION 'Reading repair conflicts with prior span: %',v_repair.id;
    END IF;
    UPDATE lexical_occurrences o
      SET start_char=v_start,end_char=v_start+length(v_repair.surface),
        sentence_text=substr(v_old.body_text,greatest(1,v_start-120),260)
      WHERE o.id=v_repair.id::uuid;
    v_repaired:=v_repaired+1;
  END LOOP;

  -- Correct polysemous meanings in 001-003 and enrich 007-009.
  FOR v_item IN
    SELECT x.kind,x.test_no,x.passage_no,x.surface,x.pos,x.uz,x.definition
    FROM (
      SELECT 'correction'::text AS kind,c."testNo" AS test_no,
        c."passageNo" AS passage_no,c.surface,c."partOfSpeech" AS pos,
        c."translationUz" AS uz,c."definitionEn" AS definition
        FROM jsonb_to_recordset(v_plan->'corrections')
        AS c("testNo" integer,"passageNo" integer,surface text,
             "partOfSpeech" text,"translationUz" text,"definitionEn" text)
      UNION ALL
      SELECT 'new'::text AS kind,t."testNo" AS test_no,
        t."passageNo" AS passage_no,t.surface,t."partOfSpeech" AS pos,
        t."translationUz" AS uz,t."definitionEn" AS definition
        FROM jsonb_to_recordset(v_plan->'terms')
        AS t("testNo" integer,"passageNo" integer,surface text,
             "partOfSpeech" text,"translationUz" text,"definitionEn" text)
    ) AS x
    ORDER BY CASE WHEN x.kind='correction' THEN 0 ELSE 1 END,
      LENGTH(x.surface) DESC,x.test_no,x.passage_no,x.surface
  LOOP
    SELECT id,body_text INTO v_passage_id,v_body FROM reading_passages
      WHERE test_no=v_item.test_no AND passage_no=v_item.passage_no;
    IF v_passage_id IS NULL THEN
      RAISE EXCEPTION 'Reading passage missing: %-%',v_item.test_no,v_item.passage_no;
    END IF;
    v_word:=lower(trim(regexp_replace(v_item.surface,'[[:space:]]+',' ','g')));
    v_part:=lower(trim(v_item.pos));
    v_regex:='(?i)(?<![[:alpha:]])'||v_item.surface||'(?![[:alpha:]])';
    v_total:=regexp_count(v_body,v_regex);
    IF v_total<1 THEN
      RAISE EXCEPTION 'Reading vocabulary surface absent: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
    END IF;
    IF v_item.kind='correction' THEN
      SELECT COUNT(*) INTO v_rows FROM lexical_occurrences
        WHERE passage_id=v_passage_id AND lower(surface_form)=v_word;
      IF v_rows<1 THEN
        RAISE EXCEPTION 'Reading correction cardinality changed: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
      END IF;
    END IF;
    v_lexical_type:=CASE v_part
      WHEN 'noun phrase' THEN 'noun_phrase'
      WHEN 'verb phrase' THEN 'verb_phrase'
      WHEN 'phrasal verb' THEN 'phrasal_verb'
      WHEN 'idiom' THEN 'idiom'
      WHEN 'collocation' THEN 'collocation'
      WHEN 'fixed expression' THEN 'fixed_expression'
      WHEN 'compound' THEN 'compound'
      WHEN 'phrase' THEN 'phrase'
      ELSE CASE WHEN position(' ' IN v_word)>0 THEN 'phrase' ELSE 'word' END
    END;
    -- Reuse a lexical unit of the same lemma, POS and lexical type.
    INSERT INTO lexical_units
      (language,lemma,lemma_norm,part_of_speech,lexical_type,
       is_function_word,provenance)
      VALUES('en',v_item.surface,v_word,v_part,v_lexical_type,false,
             'reading_context')
      ON CONFLICT(language,lemma_norm,part_of_speech,lexical_type) DO NOTHING;
    SELECT id INTO STRICT v_unit_id FROM lexical_units
      WHERE language='en' AND lemma_norm=v_word
        AND part_of_speech=v_part AND lexical_type=v_lexical_type;
    INSERT INTO lexical_unit_forms
      (lexical_unit_id,form,form_norm,form_type)
      VALUES(v_unit_id,v_item.surface,v_word,'lemma')
      ON CONFLICT(lexical_unit_id,form_norm) DO NOTHING;

    -- The v2 key is SHA256(JSON([normalised term, POS, English meaning])).
    v_sense_key:='v2:'||encode(extensions.digest(
      replace(json_build_array(v_word,v_part,lower(trim(v_item.definition)))::text,
              '", "', '","'),'sha256'),'hex');
    SELECT id INTO v_lexeme_id FROM lexemes
      WHERE sense_key=v_sense_key;
    IF v_lexeme_id IS NULL THEN
      -- Honor exact legacy senses too; do not duplicate identical meanings.
      SELECT id INTO v_lexeme_id FROM lexemes
        WHERE lower(trim(term))=v_word AND lower(trim(coalesce(part_of_speech,'')))=v_part
          AND lower(trim(definition_en))=lower(trim(v_item.definition))
        ORDER BY id LIMIT 1;
    END IF;
    IF v_lexeme_id IS NULL THEN
      INSERT INTO lexemes
        (term,part_of_speech,definition_en,translation_uz,example_sentence,
         lexical_unit_id,sense_key,provenance,verification_status,import_batch)
        VALUES(v_item.surface,v_item.pos,v_item.definition,v_item.uz,
               NULL,v_unit_id,v_sense_key,'reading_context',
               'context_checked','20261114-passages-010-012')
        ON CONFLICT(sense_key) DO NOTHING
        RETURNING id INTO v_lexeme_id;
      IF v_lexeme_id IS NULL THEN
        SELECT id INTO STRICT v_lexeme_id FROM lexemes WHERE sense_key=v_sense_key;
      END IF;
    END IF;
    SELECT coalesce(lexical_unit_id,v_unit_id) INTO v_unit_id
      FROM lexemes WHERE id=v_lexeme_id;

    IF v_item.kind='correction' THEN
      UPDATE lexical_occurrences
        SET lexeme_id=v_lexeme_id,lexical_unit_id=v_unit_id,
            resolution_status='resolved',resolution_source='context_editorial'
        WHERE passage_id=v_passage_id AND lower(surface_form)=v_word;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      v_corrected:=v_corrected+v_rows;
      CONTINUE;
    END IF;

    FOR v_ordinal IN 1..v_total LOOP
      v_start:=regexp_instr(v_body,v_regex,1,v_ordinal)-1;
      IF v_start<0 OR lower(substr(v_body,v_start+1,length(v_item.surface)))
        <> lower(v_item.surface) THEN
        RAISE EXCEPTION 'Source text shifted while linking: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
      END IF;
      -- Keep pre-existing curated multiword senses authoritative.
      IF EXISTS(SELECT 1 FROM lexical_occurrences o
          WHERE o.passage_id=v_passage_id
            AND o.start_char<v_start+length(v_item.surface)
            AND o.end_char>v_start) THEN
        CONTINUE;
      END IF;
      INSERT INTO lexical_occurrences
        (source_type,passage_id,start_char,end_char,surface_form,lexeme_id,
         lexical_unit_id,resolution_status,resolution_source,sentence_text,
         occurrence_type,is_target_vocabulary)
        VALUES('reading',v_passage_id,v_start,v_start+length(v_item.surface),
               substr(v_body,v_start+1,length(v_item.surface)),
               v_lexeme_id,v_unit_id,'resolved','context_editorial',
               substr(v_body,greatest(1,v_start-120),260),
               'vocabulary',true)
        ON CONFLICT(passage_id,start_char,end_char) DO NOTHING;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      v_inserted:=v_inserted+v_rows;
    END LOOP;
  END LOOP;
  RAISE NOTICE 'reading contextual links: repaired %, corrected %, added %',
    v_repaired,v_corrected,v_inserted;
END
$executor$;
